installer-gui-script.script:
var VERSION = '@VERSION@';
var ALLOW_DOWNGRADE = @ALLOW_DOWNGRADE@;

// Refuses to replace a newer installed SwiftCut, unless this package
// is an emergency rollback build. The same version reinstalls.
function no_downgrade() {
    var bundle = system.files.bundleAtPath('/Applications/SwiftCut.app');
    if (!bundle || !bundle.CFBundleShortVersionString || ALLOW_DOWNGRADE) {
        return true;
    }
    var installed = bundle.CFBundleShortVersionString;
    if (system.compareVersions(installed, VERSION) > 0) {
        my.result.type = 'Fatal';
        my.result.title = 'A newer SwiftCut is installed';
        my.result.message = 'SwiftCut ' + installed + ' is installed, '
            + 'which is newer than this package (' + VERSION + ').';
        return false;
    }
    return true;
}
